16	)
17	
18	// statusStyles holds pre-built lipgloss styles and terminal metadata.
19	type statusStyles struct {
20		colorEnabled bool
21		width        int
22	
23		// Styles
24		green  lipgloss.Style
25		red    lipgloss.Style
26		gray   lipgloss.Style
27		bold   lipgloss.Style
28		dim    lipgloss.Style
29		agent  lipgloss.Style // amber/orange for agent names
30		cyan   lipgloss.Style
31		yellow lipgloss.Style // yellow for stale warnings
32	}
33	
34	// newStatusStyles creates styles appropriate for the output writer.
35	func newStatusStyles(w io.Writer) statusStyles {
36		useColor := shouldUseColor(w)
37		width := getTerminalWidth(w)
38	
39		s := statusStyles{
40			colorEnabled: useColor,
41			width:        width,
42		}
43	
44		if useColor {
45			s.green = lipgloss.NewStyle().Foreground(lipgloss.Color("2"))
46			s.red = lipgloss.NewStyle().Foreground(lipgloss.Color("1"))
47			s.gray = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
48			s.bold = lipgloss.NewStyle().Bold(true)
49			s.dim = lipgloss.NewStyle().Faint(true)
50			s.agent = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("214"))
51			s.cyan = lipgloss.NewStyle().Foreground(lipgloss.Color("6"))
52			s.yellow = lipgloss.NewStyle().Foreground(lipgloss.Color("3"))
53		}
54	
55		return s
56	}
57	
58	// render applies a style to text only when color is enabled.
59	func (s statusStyles) render(style lipgloss.Style, text string) string {
60		if !s.colorEnabled {
61			return text
62		}
63		return style.Render(text)
64	}
65	
66	// shouldUseColor returns true if the writer supports color output.
67	func shouldUseColor(w io.Writer) bool {
68		return interactive.ShouldStyle(w)
69	}
70	
71	// getTerminalWidth returns the terminal width, capped at 80 with a fallback of 60.
72	// It first checks the writer itself, then falls back to Stdout/Stderr.
73	func getTerminalWidth(w io.Writer) int {
74		// Try the output writer first
75		if f, ok := w.(*os.File); ok {
76			if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
77				return min(width, 80)
78			}
79		}
80	
81		// Fall back to Stdout, then Stderr
82		for _, f := range []*os.File{os.Stdout, os.Stderr} {
83			if f == nil {
84				continue
85			}
86			if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
87				return min(width, 80)
88			}
89		}
90	
91		return 60
92	}
93	
94	// formatTokenCount formats a token count for display.
95	// 0 → "0", 500 → "500", 1200 → "1.2k", 14300 → "14.3k"
96	func formatTokenCount(n int) string {
97		if n < 1000 {
98			return strconv.Itoa(n)
99		}
100		f := float64(n) / 1000.0
101		s := fmt.Sprintf("%.1f", f)
102		// Remove trailing ".0" for clean display (e.g., 1000 → "1k" not "1.0k")
103		s = strings.TrimSuffix(s, ".0")
104		return s + "k"
105	}
106	
107	// totalTokens recursively sums all token fields including subagent tokens.
108	func totalTokens(tu *agent.TokenUsage) int {
109		if tu == nil {
110			return 0
111		}
112		total := tu.InputTokens + tu.CacheCreationTokens + tu.CacheReadTokens + tu.OutputTokens
113		total += totalTokens(tu.SubagentTokens)
114		return total
115	}
116	
117	// explainRow is one entry in a metadata block: dim label + plain value.
118	type explainRow struct {
119		Label string
120		Value string
121	}
122	
123	// identityBullet renders "● <label> <id>\n". Bullet is brand orange when color
124	// is enabled; ID is also orange to mirror the existing checkpoint header. When
125	// id is empty (e.g., temporary checkpoints append "[temporary]" to the label
126	// instead of using an id slot), the trailing space + id is suppressed.
127	func (s statusStyles) identityBullet(label, id string) string {
128		if id == "" {
129			if !s.colorEnabled {
130				return fmt.Sprintf("● %s\n", label)
131			}
132			bullet := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")), "●")
133			return fmt.Sprintf("%s %s\n", bullet, s.render(s.bold, label))
134		}
135		if !s.colorEnabled {
136			return fmt.Sprintf("● %s %s\n", label, id)
137		}
138		bullet := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")), "●")
139		idStyled := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")), id)
140		return fmt.Sprintf("%s %s %s\n", bullet, s.render(s.bold, label), idStyled)
141	}
