// viewListScrollHint returns a single line for the reserved gap row: a centered,
// dim "more results" indicator with direction arrows when the list viewport has
// rows scrolled out of view, or an empty line when the whole list fits.
func (m searchModel) viewListScrollHint() string {
	listH := m.browseVP.Height()
	total := m.browseVP.TotalLineCount()
	if listH <= 0 || total <= listH {
		return "" // everything fits — keep the gap blank
	}

	yo := m.browseVP.YOffset()
	canUp := yo > 0
	canDown := yo+listH < total

	var arrows string
	switch {
	case canUp && canDown:
		arrows = "↑↓"
	case canDown:
		arrows = "↓"
	default:
		arrows = "↑"
	}
	hint := m.styles.render(m.styles.dim, arrows+" more results")

	lead := max((m.width-lipgloss.Width(hint))/2, 0)
	return strings.Repeat(" ", lead) + hint
}

