	}

	// ── OVERVIEW ──
	w.section("OVERVIEW")
	w.field("ID", cp.ID)
	w.wrappedField("Prompt", stringutil.CollapseWhitespace(cp.Prompt))
	w.matchField(r.Meta)

	// ── SOURCE ──
	w.section("SOURCE")
