		case w.valueWidth > 0:
			w.b.WriteString(wrapText(r.Meta.Snippet, contentWidth) + "\n")
		default:
			w.b.WriteString(r.Meta.Snippet + "\n")
		}
	}

	// ── FILES ──
	if len(cp.FilesTouched) > 0 {
		w.b.WriteString("\n")
		if showSections {
			w.b.WriteString(m.styles.render(m.styles.detailTitle, "FILES") + "\n")
